sealed interface Expr {
    data class Num(val value: Int) : Expr
    data class Add(val left: Expr, val right: Expr) : Expr
}
fun eval(e: Expr, ctx: Map<String, Int>): Int = when (e) {
    is Expr.Num -> e.value
    is Expr.Add -> eval(e.left, ctx) + eval(e.right, ctx)
}

