abstract class Expression { abstract fun interpret(ctx: Context): Int }
class Num(private val value: Int) : Expression() {
    override fun interpret(ctx: Context): Int = value
}
class Add(private val left: Expression, private val right: Expression) : Expression() {
    override fun interpret(ctx: Context): Int = left.interpret(ctx) + right.interpret(ctx)
}
